/* ===== 30-solver.js ===== */
// Accords libres : forme (ex. « Am », « C/G ») -> liste de diagrammes {f:[6 cases, -1 = muette], g:[6 doigts], b:null|[case,corde de départ,corde d'arrivée]}
let customs={};
const customsFor=k=>Array.isArray(customs[k])?customs[k]:[];
const toF=s=>[...s].map(c=>c=='x'?-1:+c);
function candidates(root,q,bass){
  const out=[], seen=new Set(), name=N[root]+q, key=bass==null?name:name+'/'+BN[bass];
  const add=(f,g,b,base)=>{const k=f.join();if(seen.has(k))return;seen.add(k);out.push({f,g:[...g].map(Number),b,base,shape:name});};
  (DB[key]||[]).forEach(([f,g,b])=>add(f,g,b||null,b?1+(b[1]-b[2]+1)*0.9:0));
  if(bass!=null) return out;
  if(q==='5'||q==='5(2)'){ // power chords : 5 = fondamentale + quinte + octave (3 notes) ; 5(2) = fondamentale + quinte (2 notes)
    (q==='5'?[[4,r=>[r,r+2,r+2,-1,-1,-1]],[9,r=>[-1,r,r+2,r+2,-1,-1]],[2,r=>[-1,-1,r,r+2,r+3,-1]]]
            :[[4,r=>[r,r+2,-1,-1,-1,-1]],[9,r=>[-1,r,r+2,-1,-1,-1]],[2,r=>[-1,-1,r,r+2,-1,-1]]]).forEach(([open,fn])=>{
      const r=((root-open)%12+12)%12; if(r>9) return;
      const f=fn(r), fg=r>0?[1,3,4]:[0,1,2]; let k=0;
      add(f,f.map(v=>v>=0?fg[k++]:0),null,0);
    });
  }
  (OPEN[name]||[]).forEach(([fs,gs,b])=>add(toF(fs),gs,b||null,b?3:0));
  BARRE.forEach(([qq,form,fn,gs,from])=>{
    if(qq!==q) return;
    const r=((root-(form=='E'?4:9))%12+12)%12; if(r<1||r>9) return;
    add(fn(r),gs,[r,from,1],5+r*0.15);
  });
  return out;
}
function nodeCost(c){
  if(c.libre) return -50;   // un diagramme dessiné par l'utilisateur pour cette forme est toujours préféré (sauf si un autre est choisi à la main)
  const fr=c.f.filter(x=>x>0), mn=fr.length?Math.min(...fr):0, mx=fr.length?Math.max(...fr):0;
  const mutedInner=c.f.some((x,i)=>x<0&&i>0&&i<5&&c.f.slice(0,i).some(y=>y>=0)&&c.f.slice(i+1).some(y=>y>=0))?2:0;
  return c.base+0.4*(mx-mn)+1.2*Math.max(0,mn-3)+0.15*fr.length+mutedInner;
}
const center=c=>{const fr=c.f.filter(x=>x>0);return fr.length?fr.reduce((a,b)=>a+b)/fr.length:0};
function trans(a,b){
  let common=0; for(let i=0;i<6;i++) if(a.f[i]>0&&a.f[i]==b.f[i]&&a.g[i]==b.g[i]) common++;
  return 0.5*Math.abs(center(a)-center(b))-1.2*common;
}
function viterbi(layers,NC=nodeCost,TR=trans){ // layers: tableaux de candidats ; renvoie {path,cost}
  if(!layers.length) return {path:[],cost:0};
  let dp=layers[0].map(c=>({c:NC(c),p:-1})), hist=[dp];
  for(let i=1;i<layers.length;i++){
    dp=layers[i].map(c=>{let best=1e9,bp=0;
      hist[i-1].forEach((h,j)=>{const v=h.c+TR(layers[i-1][j],c);if(v<best){best=v;bp=j;}});
      return {c:best+NC(c),p:bp};});
    hist.push(dp);
  }
  let k=0; dp.forEach((h,j)=>{if(h.c<dp[k].c)k=j;});
  const cost=dp[k].c, path=[];
  for(let i=layers.length-1;i>=0;i--){path[i]=k;k=hist[i][k].p;}
  return {path,cost};
}
// Construit les couches de candidats pour une grille, avec capo et niveau
function build(tokens,capo,level,ov){
  return tokens.map((t,i)=>{
    const p=parse(t); if(!p||p.q===null) return {t,full:[],note:'accord non reconnu'};
    let q=p.q, note='';
    if(level=='easy'){ if(q=='m7')q='m'; else if(q=='maj7')q=''; }
    const root=((p.root-capo)%12+12)%12;
    const bs=(p.bass!==null&&p.bass!==p.root)?((p.bass-capo)%12+12)%12:null;
    const lkey=N[root]+q+(bs!==null?'/'+N[bs]:''), cu=customsFor(lkey);   // accords libres de cette forme (indépendants du capo : la forme est celle qu'on joue)
    let full=candidates(root,q,bs);
    if(!full.length&&bs!==null){full=candidates(root,q); if(full.length) note='sans la basse';}
    if(!full.length&&q!==''&&q!=='m'){ // repli sur l'accord de base
      const base=q.startsWith('m')&&q!='maj7'?'m':''; full=candidates(root,base);
      if(full.length) note='simplifié en '+N[root]+base;
    }
    if(!full.length&&!cu.length) return {t,full:[],note:'pas de diagramme',libreKey:lkey};
    full.sort((a,b)=>nodeCost(a)-nodeCost(b)); full=full.slice(0,6); cu.forEach(x=>full.push({...x,libre:true,base:0,shape:lkey})); full.forEach((c,j)=>c.id=j);   // les libres viennent après : les numéros de variante des autres ne bougent pas
    return {t,full,note:cu.length&&note==='pas de diagramme'?'':note,pool:ov[i]!=null?[full[ov[i]%full.length]]:full,shape:N[root]+q,libreKey:lkey};
  });
}
function solve(items,NC,TR){
  const idx=items.map((x,i)=>x.full.length?i:-1).filter(i=>i>=0);
  const r=viterbi(idx.map(i=>items[i].pool),NC,TR);
  const chosen={}; idx.forEach((i,k)=>chosen[i]=items[i].pool[r.path[k]]);
  return {chosen,cost:r.cost};
}
// Dessin SVG
const STR_W=[1.54,1.26,0.98,0.73,0.6,0.6]; // épaisseur des 6 cordes, de la plus grave (mi) à la plus aiguë (mi) : 70 % des valeurs de la 1.2.0, sauf les deux plus fines, identiques (0,6)
function svg(c,prev,st){
  const pvb=!!(prev&&prev.b&&c.b&&prev.b[0]===c.b[0]&&prev.b[1]===c.b[1]&&prev.b[2]===c.b[2]);   // même barré que l'accord précédent
  const X=i=>16+i*12.1, top=24, fh=15, rows=5;   // écart entre cordes : 12,1 (+10 % par rapport à 11)
  const fr=c.f.filter(x=>x>0), mx=fr.length?Math.max(...fr):0, mn=fr.length?Math.min(...fr):1;
  const start=st||(mx<=5?1:mn);
  let s=`<svg viewBox="0 0 100 106" role="img" aria-label="diagramme" fill="none" stroke="currentColor" stroke-width="1">`;
  for(let i=0;i<6;i++) s+=`<line x1="${X(i)}" y1="${top}" x2="${X(i)}" y2="${top+rows*fh}"${thick?` stroke-width="${STR_W[i]}"`:''}/>`;
  for(let j=0;j<=rows;j++) s+=`<line x1="${X(0)}" y1="${top+j*fh}" x2="${X(5)}" y2="${top+j*fh}" ${j==0&&start==1?'stroke-width="3"':''}/>`;
  if(start>1) s+=`<text x="${X(5)+6}" y="${top+fh*0.5+4}" font-size="11.25" fill="currentColor" stroke="none">${start}</text>`;
  c.f.forEach((f,i)=>{ if(f<0) s+=`<text x="${X(i)}" y="16" font-size="10" text-anchor="middle" fill="currentColor" stroke="none">×</text>`;
    else if(f==0) s+=`<circle cx="${X(i)}" cy="12" r="3" stroke-width="1.2"/>`;});
  if(c.b){const [bf,a,z]=c.b,x1=X(6-a),x2=X(6-z),y=top+(bf-start+0.5)*fh;
    s+=`<rect x="${x1-5}" y="${y-5}" width="${x2-x1+10}" height="10" rx="5" fill="${pvb?'var(--pivot)':'var(--accent)'}" ${pvb?'stroke="var(--ink)" stroke-width="1.4"':'stroke="none"'}/>`;}
  c.f.forEach((f,i)=>{ if(f<=0) return;
    const inBar=c.b&&f==c.b[0]&&(6-i)<=c.b[1]&&(6-i)>=c.b[2];
    const y=top+(f-start+0.5)*fh;
    const pv=!!(prev&&prev.f[i]===f);   // même corde, même case que l'accord précédent : le doigt reste en place
    if(!inBar) s+=`<circle cx="${X(i)}" cy="${y}" r="5.5" fill="${pv?'var(--pivot)':'var(--accent)'}" ${pv?'stroke="var(--ink)" stroke-width="1.4"':'stroke="none"'}/>`;
    if(digits&&c.g[i]&&!inBar) s+=`<text x="${X(i)}" y="${y+3.3}" font-size="9" font-weight="700" text-anchor="middle" fill="${pv?'var(--pivot-ink)':'var(--accent-ink)'}" stroke="none">${c.g[i]}</text>`;});
  if(c.b&&digits){const y=top+(c.b[0]-start+0.5)*fh;
    s+=`<text x="${X(6-c.b[1])}" y="${y+3.3}" font-size="9" font-weight="700" text-anchor="middle" fill="${pvb?'var(--pivot-ink)':'var(--accent-ink)'}" stroke="none">1</text>`;}
  return s+'</svg>';
}
