// --- Grille éditable : une case par temps. Un accord tient jusqu'au prochain changement (un événement d'accord = une case marquée). ---
function slotsHTML(){
  const n=chords.length, bars=n/BPB;
  let h='';
  for(let m=0;m<bars;m++){
    h+=`<div class="bar" role="group" aria-label="Mesure ${m+1}"><span class="bn" aria-hidden="true">${m+1}</span>`;
    for(let t=0;t<BPB;t++){
      const b=m*BPB+t, chg=b===0||chords[b]!==chords[b-1];
      h+=`<button class="chip beat${chg?' chg':t===0?' c0':' cont'}" data-b="${b}" aria-label="Mesure ${m+1}, temps ${t+1} : ${esc(chords[b])}${chg?'':' (suite)'}">${chg||t===0?esc(chords[b]):'·'}</button>`;
    }
    h+='</div>';
  }
  h+='<div class="barbtns"><button class="chip add" id="add" aria-label="Ajouter une mesure">+ Mesure</button>'+(bars>1?'<button class="chip add" id="rmBar" aria-label="Retirer la dernière mesure">− Mesure</button>':'')+'</div>';
  $('slots').innerHTML=h;
  const gt=$('gtxt'); if(gt&&document.activeElement!==gt) gt.value=gridText(chords);
}
// Les choix manuels et verrous sont rangés par temps de départ de série : après une modification de la grille, on ne garde que ceux dont
// la série existe toujours au même endroit avec le même accord (remap : ancien temps -> nouveau temps, ou null si la série a disparu).
function runStarts(arr){ const o={}; let p=null; arr.forEach((c,b)=>{ if(c!==p){ o[b]=c; p=c; } }); return o; }
function fixPins(oldCh,newCh,remap){
  const to=runStarts(oldCh), tn=runStarts(newCh);
  [['ov','lk'],['ovP','lkP']].forEach(([a,l])=>{
    const P=a==='ov'?ov:ovP, L=l==='lk'?lk:lkP, nP={}, nL={};
    new Set([...Object.keys(P),...Object.keys(L)]).forEach(ks=>{ const k=+ks, k2=remap?remap(k):k;
      if(k2==null||to[k]===undefined||to[k]!==tn[k2]) return;
      if(P[k]!=null) nP[k2]=P[k]; if(L[k]!=null) nL[k2]=L[k]; });
    if(a==='ov'){ ov=nP; lk=nL; } else { ovP=nP; lkP=nL; }
  });
}
function editChords(fn,remap){ const old=chords.slice(); fn(); fixPins(old,chords,remap); }
const addBar=()=>{ if(chords.length/BPB>=MAX_BARS) return; const last=chords[chords.length-1]||'C'; editChords(()=>{ for(let j=0;j<BPB;j++) chords.push(last); }); };
const removeBarAt=m=>{ if(chords.length<=BPB) return; const lo=m*BPB; editChords(()=>chords.splice(lo,BPB),k=>k<lo?k:k>=lo+BPB?k-BPB:null); };
