const QUAL=[['','–','Majeur'],['m','m','Mineur'],['7','7'],['m7','m7'],['maj7','maj7'],['sus2','sus2'],['sus4','sus4'],['5','5 (3)','Power chord à 3 notes'],['5(2)','5 (2)','Power chord à 2 notes']];
