   +`<div class="col"><h3>Type</h3><div class="opts two">${QUAL.map(([v,t,a])=>o(v,t,sel.q==v,'q','',a)).join('')}</div></div>`
   +`<div class="col"><h3>Basse</h3><div class="opts two">${o('','Aucune',!sel.b,'b',' full')+N.map(n=>o(n,n,sel.b==n,'b')).join('')}</div></div>`;
  $('sheetT').textContent=`Mesure ${barOf(cur)} · temps ${beatOf(cur)} : ${chords[cur]}${isChange(cur)?'':' (suite)'}`;
