/* ===== 45-piano.js ===== */
// ==PIANO==
const IV={'':[0,4,7],'5':[0,7],'5(2)':[0,7],m:[0,3,7],'7':[0,4,7,10],m7:[0,3,7,10],maj7:[0,4,7,11],sus2:[0,2,7],sus4:[0,5,7]};
const INV=['position fondamentale','1er renversement','2e renversement','3e renversement'];
// Main droite : un renversement par candidat (note la plus grave entre do4 et si4) ; main gauche : la basse (do3 à si3)
function pianoCands(root,q,bassPc){
  const pcs=IV[q].map(i=>(root+i)%12), bm=48+((bassPc-48)%12+12)%12, out=[];
  pcs.forEach((_,k)=>{
    const ord=pcs.slice(k).concat(pcs.slice(0,k));
    let p=60+((ord[0]-60)%12+12)%12; const n=[p];
    for(let j=1;j<ord.length;j++){p+=((ord[j]-ord[j-1])%12+12)%12||12; n.push(p);}
    if(q==='5') n.push(n[0]+12);
    out.push({n,inv:k,bm});
  });
  return out;
}
function nodeCostP(c){const n=c.n, sp=n[n.length-1]-n[0], ctr=(n[0]+n[n.length-1])/2; return 0.25*sp+0.1*Math.abs(ctr-68)+(c.inv?0.4:0);}
function transP(a,b){
  const d=(x,y)=>x.reduce((s,v)=>s+Math.min(...y.map(w=>Math.abs(v-w))),0);
  return 0.7*(d(a.n,b.n)+d(b.n,a.n))/2-0.8*a.n.filter(v=>b.n.includes(v)).length+0.06*Math.abs(a.bm-b.bm);
}
function buildP(tk,lvl,ovr){
  return tk.map((t,i)=>{
    const p=parse(t); if(!p||p.q===null) return {t,full:[],note:'accord non reconnu'};
    let q=p.q; if(lvl=='easy'){if(q=='m7')q='m'; else if(q=='maj7')q='';}
    const full=pianoCands(p.root,q,p.bass!==null?p.bass:p.root);
    full.sort((a,b)=>nodeCostP(a)-nodeCostP(b)); full.forEach((c,j)=>c.id=j);
    return {t,full,pool:ovr[i]!=null?[full[ovr[i]%full.length]]:full};
  });
}
function modelP(ovr){
  const runs=[]; tokens().forEach((t,i)=>{const l=runs[runs.length-1]; if(l&&l.t==t) l.n++; else runs.push({t,i,n:1});});
  const rov={}; runs.forEach((r,k)=>{if(ovr[r.i]!=null) rov[k]=ovr[r.i];});
  const items=buildP(runs.map(r=>r.t),$('lvl').value,rov);
  return {runs,items,rov,...solve(items,nodeCostP,transP)};
}
function svgP(c,prev){
  const lo=48,hi=83,kw=10,wh=50,bh=31,bw=6.4, W=[0,2,4,5,7,9,11], rh=new Set(c.n);
  const pv=m=>!!(prev&&rh.has(m)&&prev.n.includes(m)), ring=m=>pv(m)?' stroke="var(--ink)" stroke-width="1.4"':'';   // note déjà jouée par l'accord précédent
  const fill=(m,d)=>rh.has(m)?(pv(m)?'var(--pivot)':'var(--accent)'):m==c.bm?'var(--bass)':d;
  let s=`<svg viewBox="0 0 ${21*kw} ${wh+2}" role="img" aria-label="clavier" stroke="var(--keyline)" stroke-width=".8">`, wi=0, bl=[];
  for(let m=lo;m<=hi;m++){ if(W.includes(m%12)){s+=`<rect x="${wi*kw}" y="1" width="${kw}" height="${wh}" fill="${fill(m,'var(--key)')}"${ring(m)}/>`; wi++;} else bl.push([m,wi]); }
  bl.forEach(([m,w])=>{s+=`<rect x="${w*kw-bw/2}" y="1" width="${bw}" height="${bh}" rx="1" fill="${fill(m,'var(--blackkey)')}"${ring(m)}/>`;});
  return s+'</svg>';
}
function renderP(){
  const {runs,items,chosen}=modelP(ovP);
  $('grid').innerHTML=items.map((it,i)=>{
    const c=chosen[i], rep=durText(runs[i].n), pp=pivots&&i>0?chosen[i-1]||null:null, pt=pp?pivotTextP(c,pp):'';
    if(!c) return `<div class="card pn" style="cursor:default"><b>${esc(it.t)}</b><small>${[rep,it.note].filter(Boolean).join(' · ')}</small></div>`;
    const nm=m=>N[m%12];
    return `<div class="cw"><div class="card pn${lkP[runs[i].i]?' lkd':''}" tabindex="0" role="button" data-i="${i}" aria-label="${esc(it.t)} : changer de renversement${lkP[runs[i].i]?' (verrouillé)':''}"><b>${esc(it.t)}</b>${svgP(c,pp)}<small>${[rep,INV[c.inv],pt].filter(Boolean).join(' · ')}</small><small>MG ${nm(c.bm)} · MD ${c.n.map(nm).join(' ')}</small></div>${cardBar(i,it.t,!!lkP[runs[i].i])}</div>`;
  }).join('');
}
