// Thème : variables CSS (voir theme.css) + réglages possibles dans l'adresse, utiles pour intégrer l'appli dans un autre projet.
// Ex. ?theme=dark&accent=ff6600&bg=101418&radius=4&font=Georgia&strings=1
const COLORS={bg:'--bg',panel:'--panel',ink:'--ink',muted:'--muted',line:'--line',accent:'--accent',accentink:'--accent-ink',warn:'--warn',bass:'--bass',key:'--key',keyline:'--keyline',blackkey:'--blackkey',pivot:'--pivot',pivotink:'--pivot-ink'};

/* ===== 60-theme-view.js ===== */
function parseTheme(search){
  const q=new URLSearchParams(search), out={theme:null,strings:null,vars:{}};
  if(['light','dark','auto'].includes(q.get('theme'))) out.theme=q.get('theme');
  if(['0','1'].includes(q.get('strings'))) out.strings=q.get('strings')==='1';
  const z=parseFloat(q.get('zoom')); if(z>=0.5&&z<=4) out.zoom=z;
  if(['0','1'].includes(q.get('pivots'))) out.pivots=q.get('pivots')==='1';
  if(['0','1'].includes(q.get('digits'))) out.digits=q.get('digits')==='1';
  for(const [name,prop] of Object.entries(COLORS)){const v=q.get(name); if(v&&/^#?[0-9a-f]{3,8}$/i.test(v)) out.vars[prop]='#'+v.replace(/^#/,'');}
  const r=q.get('radius'); if(r&&/^\d{1,2}(px|rem)?$/.test(r)) out.vars['--radius']=/\D/.test(r)?r:r+'px';
  [['font','--font-body'],['fonttitle','--font-title']].forEach(([name,prop])=>{const v=q.get(name); if(v&&/^[\w ,'"-]{1,80}$/.test(v)) out.vars[prop]=v;});
  return out;
}
