  const disarm=()=>{ lb.classList.remove('arming'); if(lockTimer){ clearTimeout(lockTimer); lockTimer=null; vmsg(locked?'Maintenez le cadenas appuyé pour déverrouiller.':'Maintenez le cadenas appuyé pour verrouiller.'); } };
