// ==PIVOT==
// Doigts en place : un doigt reste en place si l'accord suivant utilise la même corde et la même case (guitare),
// une note reste en place si l'accord précédent la contient déjà (piano).
function pivotText(c,p){
  if(!c||!p) return '';
  const idx=[]; c.f.forEach((f,i)=>{ if(f>0&&p.f[i]===f) idx.push(i); });
  if(!idx.length) return 'aucun doigt en place';
  const n=new Set(idx.map(i=>c.g[i]||('s'+i))).size;   // une corde barrée ne compte que pour un doigt
  return n+(n>1?' doigts en place':' doigt en place');
}
function pivotTextP(c,p){
  if(!c||!p) return '';
  const n=c.n.filter(m=>p.n.includes(m)).length;
  return n?n+(n>1?' notes en place':' note en place'):'aucune note en place';
}
// ==/PIVOT==

/* ===== 70-audio.js ===== */
// ==AUDIO==
// Moteur sonore : un seul AudioContext (créé au premier geste de l'utilisateur, obligatoire sur téléphone et tablette),
// des notes préparées par la synthèse (==SYNTH==), et un planificateur « avec avance » : un minuteur de 25 ms programme
// les sons des 250 ms à venir sur l'horloge audio, qui seule est assez précise pour tenir le tempo.
const EAR_SVG='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4z"/><path d="M16.5 8.5a5 5 0 0 1 0 7"/><path d="M19 6a8.5 8.5 0 0 1 0 12"/></svg>';
// --- Verrou par accord : un diagramme verrouillé ne change plus (clic, ajout / suppression d'accords, recalcul), jusqu'à ce qu'on le déverrouille ----
// Un verrou garde le CONTENU du diagramme (frettes / notes), pas un numéro de variante : si le capo, le niveau ou l'accord change et que ce diagramme n'existe plus, le verrou est levé et on le dit.
const keyG=c=>c.f.join(), keyP=c=>c.n.join()+'|'+c.bm;
const LK_O='<svg class="o" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 7.5-1.8"/></svg>';
const LK_C='<svg class="c" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>';
const lockBtn=(i,t,on)=>`<button class="clk${on?' on':''}" data-i="${i}" aria-pressed="${on}" aria-label="${on?'Déverrouiller':'Verrouiller'} ${esc(t)} (appui long)" title="Appui long pour ${on?'déverrouiller':'verrouiller'} ce diagramme">${LK_O}${LK_C}</button>`;
const cardBar=(i,t,on,pen)=>`<div class="cb">${earBtn(i,t)}${pen?penBtn(i,t):''}${lockBtn(i,t,on)}</div>`;
// Après un ajout (i = -1) ou une suppression de l'accord i : seuls les choix verrouillés sont gardés, décalés si besoin ; les autres se recalculent.
function keepLocked(i){
  [['ov','lk'],['ovP','lkP']].forEach(([a,b])=>{
    const P=a==='ov'?ov:ovP, L=b==='lk'?lk:lkP, nP={}, nL={};
    Object.keys(L).forEach(k=>{ k=+k; if(i>=0&&k===i) return; const j=i>=0&&k>i?k-1:k; nL[j]=L[k]; if(P[k]!=null) nP[j]=P[k]; });
    if(a==='ov'){ ov=nP; lk=nL; } else { ovP=nP; lkP=nL; }
  });
}
function reconcileLocks(){   // appelée à chaque affichage : lève les verrous dont le diagramme n'existe plus
  let lost=0;
  [[lk,ov,model,keyG],[lkP,ovP,modelP,keyP]].forEach(([L,P,mdl,key])=>{
    const ks=Object.keys(L); if(!ks.length) return; const m=mdl(P);
    ks.forEach(i=>{ const k=m.runs.findIndex(r=>r.i==i), c=k<0?null:m.chosen[k]; if(!c||P[i]==null||key(c)!==L[i]){ delete L[i]; delete P[i]; lost++; } });
  });
  if(lost) vmsg(lost>1?`${lost} verrous ont été levés : le diagramme verrouillé n'existe plus (capo, niveau ou accord modifié).`:"Un verrou a été levé : le diagramme verrouillé n'existe plus (capo, niveau ou accord modifié).");
}
function toggleChordLock(k){
  const g=tab==='g', m=g?model(ov):modelP(ovP), P=g?ov:ovP, L=g?lk:lkP, c=m.chosen[k], r=m.runs[k]; if(!c) return;
  if(L[r.i]){ delete L[r.i]; vmsg('Diagramme déverrouillé : un appui le change de nouveau.'); }
  else { P[r.i]=c.id; L[r.i]=g?keyG(c):keyP(c); vmsg('Diagramme verrouillé : il ne change plus, même si vous modifiez le reste de la grille.'); }
  try{ navigator.vibrate&&navigator.vibrate(30); }catch(_){}
  render();
}
const CLK_MS=600; let clkTimer=null, clkBtn=null;
function clkArm(b){ if(clkTimer||locked) return; clkBtn=b; b.classList.add('arming'); clkTimer=setTimeout(()=>{ const x=clkBtn; clkTimer=null; clkBtn=null; x.classList.remove('arming'); toggleChordLock(+x.dataset.i); },CLK_MS); }
function clkDisarm(){ if(!clkTimer) return; clearTimeout(clkTimer); clkTimer=null; if(clkBtn) clkBtn.classList.remove('arming'); clkBtn=null; vmsg('Maintenez le petit cadenas appuyé pour verrouiller ou déverrouiller ce diagramme.'); }
$('grid').addEventListener('pointerdown',e=>{ const b=e.target.closest&&e.target.closest('.clk'); if(b&&e.button<=0) clkArm(b); });
['pointerup','pointercancel'].forEach(t=>document.addEventListener(t,clkDisarm));
$('grid').addEventListener('keydown',e=>{ const b=e.target.closest&&e.target.closest('.clk'); if(b&&(e.key==='Enter'||e.key===' ')&&!e.repeat){ e.preventDefault(); e.stopPropagation(); clkArm(b); } });
$('grid').addEventListener('keyup',e=>{ if(e.target.closest&&e.target.closest('.clk')&&(e.key==='Enter'||e.key===' ')) clkDisarm(); });
const earBtn=(i,t)=>`<button class="ear" data-i="${i}" aria-label="Écouter ${esc(t)}" title="Écouter cet accord">${EAR_SVG}</button>`;
const NOSOUND="Le son n'est pas disponible dans ce navigateur.";
const SF_FILES={lib:'vendor/spessa-lib.js',processor:'vendor/spessasynth_processor.min.js',bank:'sons/note-all.sf3'};   // à côté de la page
const SF_GAIN=2;   // niveau de la banque de sons avant le limiteur (réglé par mesure, à valider à l'oreille)
const Snd={
  ctx:null, out:null, cache:new Map(), voices:[], seq:null, timer:null,
  // ---- Banque de sons (SoundFont) : moteur par défaut quand les fichiers sont présents à côté de la page (PWA hébergée) ----
  // Le synthé (SpessaSynth, dans vendor/) tourne dans un AudioWorklet ; les notes lui sont envoyées avec leur heure (horloge audio),
  // reculée du retard du synthé (≈ 80 ms, mesuré à partir des messages de l'horloge qu'il envoie). Ses « note off » ne sont postés qu'à
  // l'échéance : un événement daté déjà posté ne peut plus être retiré. Sans les fichiers (artefact, page ouverte à plat), les sons intégrés prennent le relais.
  drumGo:false, drumWarm:false, wantDrums:false, sfState:'idle', sf:null, sfData:null, sfp:null, sfBusy:false, warmed:false, lag:0.08, lags:[], offs:[], offTimer:null,
  sfOn(){ return this.sfState==='ready'&&sndSel.value!=='builtin'; },
  sfFetch(){   // télécharge (ou relit dans le cache du service worker) la banque, le processeur du worklet et la bibliothèque : aucun geste requis
    if(this.sfp) return this.sfp;
    this.sfState='fetching'; setSndMsg('Banque de sons : chargement…');
    const get=async(url,text)=>{ const r=await fetch(url); if(!r.ok) throw new Error(url+' : HTTP '+r.status); return text?r.text():r.arrayBuffer(); };
    this.sfp=(async()=>{
      const [bank,proc]=await Promise.all([get(SF_FILES.bank),get(SF_FILES.processor,true)]);
      const b=new Uint8Array(bank,0,12), tag=(i,t)=>[...t].every((ch,k)=>b[i+k]===ch.charCodeAt(0));
      if(b.length<12||!tag(0,'RIFF')||!tag(8,'sfbk')) throw new Error('banque de sons invalide');
      if(!(window.SpessaLib&&window.SpessaLib.WorkletSynthesizer)) await new Promise((ok,ko)=>{ const sc=document.createElement('script'); sc.src=SF_FILES.lib; sc.onload=ok; sc.onerror=()=>ko(new Error('bibliothèque introuvable')); document.head.appendChild(sc); });
      if(!(window.SpessaLib&&window.SpessaLib.WorkletSynthesizer)) throw new Error('bibliothèque invalide');
      this.sfData={bank,proc}; this.sfState='fetched';
      try{ if(navigator.storage&&navigator.storage.persist) navigator.storage.persist(); }catch(_){}   // demande de garder les fichiers sur l'appareil
      if(this.ctx) this.sfStart();
    })().catch(()=>{ this.sfState='failed'; setSndMsg('Banque de sons indisponible ici : sons intégrés.'); });
    return this.sfp;
  },
  async sfStart(){   // construit le synthé (après un geste : il faut un AudioContext)
    if(this.sfState!=='fetched'||this.sfBusy||!this.ctx) return;
    this.sfBusy=true; this.sfState='building'; setSndMsg('Banque de sons : préparation…');
    try{
      const c=this.ctx, code=this.sfData.proc, urls=[]; let ok=false, last=null;
      try{ urls.push(URL.createObjectURL(new Blob([code],{type:'text/javascript'}))); }catch(_){}
      urls.push('data:text/javascript;charset=utf-8,'+encodeURIComponent(code));   // repli : certaines pages refusent les adresses blob:
      for(const u of urls){ try{ await c.audioWorklet.addModule(u); ok=true; break; }catch(e){ last=e; } }
      if(!ok) throw last||new Error('worklet');
      const synth=new window.SpessaLib.WorkletSynthesizer(c); synth.connect(this.sfGain);
      const port=synth.worklet&&synth.worklet.port;
      if(port){ port.addEventListener('message',ev=>{ const t=ev&&ev.data&&ev.data.currentTime; if(!Number.isFinite(t)) return;
        this.lags.push(c.currentTime-t); if(this.lags.length>16) this.lags.shift(); this.lag=Math.min(0.5,Math.max(0,Math.min(...this.lags))); }); if(port.start) port.start(); }
      await synth.soundBankManager.addSoundBank(this.sfData.bank.slice(0),'main'); await synth.isReady;
      if(synth.setSystemParameter) synth.setSystemParameter('voiceCap',128);
      this.sf=synth; this.sfProgram(); this.sfState='ready'; setSndMsg('Banque de sons prête.'); this.sfWarm(); if(this.wantDrums) this.sfWarmDrums();
    }catch(e){ this.sfState='failed'; this.sf=null; setSndMsg('Banque de sons indisponible : sons intégrés.'); }
    this.sfBusy=false;
  },
  sfProgram(){   // canal 0 : guitare (acier 25 ou nylon 24), canal 1 : piano (0)
    const s=this.sf; if(!s) return;
    [[0,sndSel.value==='sf-nylon'?24:25],[1,0],[2,33]].forEach(([ch,p])=>{ s.controllerChange(ch,0,0); s.controllerChange(ch,32,0); s.programChange(ch,p); });
  },
  // Un SF3 décompresse chaque échantillon à la première note qui l'utilise, dans le fil audio : on joue donc une fois, en silence (canal 15, volume 0),
  // des notes de tout l'ambitus avec les vélocités utilisées, pour que la première vraie écoute ne saccade pas.
  sfWarm(){
    if(this.warmed||!this.sf) return; this.warmed=true;
    const s=this.sf, ch=15, jobs=[];
    [[sndSel.value==='sf-nylon'?24:25,40,86,[92,100]],[0,48,83,[88,100]],[33,28,52,[70,100]]].forEach(([p,a,b,vs])=>{ jobs.push({p}); for(let k=a;k<=b;k+=2) vs.forEach(v=>jobs.push({k,v})); });
    s.controllerChange(ch,7,0); s.controllerChange(ch,0,0); s.controllerChange(ch,32,0);
    let i=0; const step=()=>{ if(this.sf!==s||i>=jobs.length) return;
      for(let n=0;n<2&&i<jobs.length;n++){ const j=jobs[i++]; if(j.p!==undefined) s.programChange(ch,j.p); else { s.noteOn(ch,j.k,j.v); s.noteOff(ch,j.k); } }
      setTimeout(step,60); };
    step();
  },
  // Batterie (canal 9, kit « Standard » de la banque) : mêmes précautions que pour les notes ; préchauffage silencieux (volume du canal à 0) à l'ouverture de l'entraînement.
  sfWarmDrums(){
    const s=this.sf; if(!s||this.drumWarm) return; this.drumWarm=true; this.drumGo=false;
    const jobs=[]; Object.values(DRUMS).forEach(([k,lo,hi])=>[lo,hi].forEach(v=>jobs.push([k,v])));
    s.controllerChange(9,7,0); let i=0;
    const step=()=>{ if(this.sf!==s||this.drumGo) return; if(i>=jobs.length){ s.controllerChange(9,7,DRUM_VOL); this.drumGo=true; return; }
      for(let n=0;n<2&&i<jobs.length;n++){ const [k,v]=jobs[i++]; s.noteOn(9,k,v); s.noteOff(9,k); } setTimeout(step,60); };
    step();
  },
  drumsReady(){ this.drumGo=true; if(this.sf&&this.drumWarm) this.sf.controllerChange(9,7,DRUM_VOL); },   // au départ : le canal reprend son volume même si le préchauffage n'est pas fini
  bass(midi,when,dur,force){   // une note de basse (canal 2 de la banque, sinon basse synthétisée) ; elle s'éteint après dur secondes
    if(!this.ctx) return;
    if(this.sfOn()){
      this.sf.noteOn(2,midi,Math.round(60+55*Math.max(0,Math.min(1,force))),{time:when-this.lag}); this.offs.push({time:when+dur,t0:when,ch:2,key:midi});
      if(!this.offTimer) this.offTimer=setInterval(()=>this.sfPump(),30);
    } else {
      const c=this.ctx, k='b'+midi; let b=this.cache.get(k);
      if(!b){ const d=renderBass(c.sampleRate,midi); b=c.createBuffer(1,d.length,c.sampleRate); b.getChannelData(0).set(d); this.cache.set(k,b); }
      const src=c.createBufferSource(), g=c.createGain(), v={src,g,t0:when,rel:false,drum:true};   // « drum » : un changement d'accord ne coupe pas ce son
      src.buffer=b; g.gain.value=0.6*force; g.gain.setTargetAtTime(0,when+dur,0.04); src.connect(g); g.connect(this.out);
      src.onended=()=>{ const i=this.voices.indexOf(v); if(i>=0) this.voices.splice(i,1); try{ g.disconnect(); }catch(_){} };
      this.voices.push(v); src.start(when); src.stop(when+dur+0.4);
    }
  },
  dbuf(kind){ const k='d'+kind; let b=this.cache.get(k); if(!b){ const c=this.ctx, d=renderDrum(c.sampleRate,kind); b=c.createBuffer(1,d.length,c.sampleRate); b.getChannelData(0).set(d); this.cache.set(k,b); } return b; },
  drum(kind,when,force){
    const def=DRUMS[kind]; if(!def||!this.ctx) return;
    if(this.sfOn()){
      const v=Math.round(def[1]+(def[2]-def[1])*Math.max(0,Math.min(1,force)));
      this.sf.noteOn(9,def[0],v,{time:when-this.lag}); this.offs.push({time:when+0.4,t0:when,ch:9,key:def[0]});
      if(!this.offTimer) this.offTimer=setInterval(()=>this.sfPump(),30);
    } else {
      const c=this.ctx, src=c.createBufferSource(), g=c.createGain(), v={src,g,t0:when,rel:false,drum:true};
      src.buffer=this.dbuf(kind); g.gain.value=0.55*force; src.connect(g); g.connect(this.drumOut);
      src.onended=()=>{ const i=this.voices.indexOf(v); if(i>=0) this.voices.splice(i,1); try{ g.disconnect(); }catch(_){} };
      this.voices.push(v); src.start(when);
    }
  },
  chordSF(kind,notes,when){
    const s=this.sf, ch=kind==='piano'?1:0, hold=kind==='piano'?4.5:3.5;
    notes.forEach((m,i)=>{
      const t=when+(kind==='piano'?i*0.006:i*0.024), vel=kind==='piano'?(i===0?100:88):Math.round(96+4*Math.sin(i*2.1));
      this.offs.forEach(o=>{ if(o.ch===ch&&o.key===m&&o.time>t-0.004) o.time=Math.max(o.t0,t-0.004); });   // même touche encore tenue : on la relâche juste avant de la rejouer
      s.noteOn(ch,m,vel,{time:t-this.lag});
      this.offs.push({time:t+hold,t0:t,ch,key:m});
    });
    if(!this.offTimer) this.offTimer=setInterval(()=>this.sfPump(),30);
  },
  sfPump(){   // poste les « note off » arrivés à échéance (dans les 120 ms)
    const c=this.ctx, s=this.sf;
    if(c&&s){ const hz=c.currentTime+0.12, keep=[]; this.offs.forEach(o=>{ if(o.time<hz) s.noteOff(o.ch,o.key,{time:o.time-this.lag}); else keep.push(o); }); this.offs=keep; }
    else this.offs=[];
    if(!this.offs.length){ clearInterval(this.offTimer); this.offTimer=null; }
  },
  sfSilence(){
    const s=this.sf; if(!s) return; this.offs=[]; s.stopAll(true);
    [40,120,300].forEach(ms=>setTimeout(()=>{ if(this.sf===s&&!this.offs.length) s.stopAll(true); },ms));   // une note postée juste avant la coupure peut arriver après : on recoupe
  },
  ready(){   // à appeler depuis un geste (clic, toucher)
    if(!this.ctx){
      const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return false;
      try{ this.ctx=new AC(); }catch(_){ this.ctx=null; return false; }
      const c=this.ctx, lp=c.createBiquadFilter(), comp=c.createDynamicsCompressor(), g=c.createGain();
      lp.type='lowpass'; lp.frequency.value=7000; comp.threshold.value=-3; comp.knee.value=6; comp.ratio.value=10; g.gain.value=0.9;   // le compresseur n'est qu'un limiteur de sécurité : les accords ont une crête d'environ 0,7 avant lui
      lp.connect(comp); comp.connect(g); g.connect(c.destination); this.out=lp; this.comp=comp;
      this.sfGain=c.createGain(); this.sfGain.gain.value=SF_GAIN; this.sfGain.connect(comp);
      this.drumOut=c.createGain(); this.drumOut.gain.value=1; this.drumOut.connect(comp);   // batterie intégrée : sans le filtre à 7 kHz (charleston, ride)   // la banque de sons arrive directement (pas de filtre à 7 kHz : cymbales et charleston)
    }
    if(this.ctx.state!=='running'){ try{ this.ctx.resume(); }catch(_){} }
    if(this.sfState==='fetched') this.sfStart();   // la banque est téléchargée : on construit le synthé maintenant que le geste a eu lieu
    return true;
  },
  buffer(kind,midi){
    const k=kind+midi; let b=this.cache.get(k);
    if(!b){
      if(this.cache.size>96) this.cache.clear();
      const c=this.ctx, data=(kind==='piano'?renderPiano:renderGuitar)(c.sampleRate,midi);
      b=c.createBuffer(1,data.length,c.sampleRate); b.getChannelData(0).set(data); this.cache.set(k,b);
    }
    return b;
  },
  note(kind,midi,when,vel){
    const c=this.ctx, src=c.createBufferSource(), g=c.createGain(), v={src,g,t0:when,rel:false,kind};
    src.buffer=this.buffer(kind,midi); g.gain.value=vel; src.connect(g); g.connect(this.out);
    src.onended=()=>{ const i=this.voices.indexOf(v); if(i>=0) this.voices.splice(i,1); try{ g.disconnect(); }catch(_){} };
    this.voices.push(v); src.start(when);
  },
  // Un accord : guitare = coup de médiator vers le bas (du grave à l'aigu, 24 ms entre cordes) ; piano = notes presque ensemble, basse en premier.
  chord(kind,notes,when){
    if(this.sfOn()) return this.chordSF(kind,notes,when);
    if(kind==='piano') notes.forEach((m,i)=>this.note('piano',m,when+i*0.006,i===0?0.47:0.37));
    else notes.forEach((m,i)=>this.note('guitar',m,when+i*0.024,0.5*(0.92+0.08*Math.sin(i*2.1))));
  },
  release(when,tc=0.04,kind){   // éteint les notes déjà lancées avant « when » (changement d'accord) ; kind : 'guitar' ou 'piano' pour ne couper que cet instrument
    const c=this.ctx, t=Math.max(when,c.currentTime), chOf=kind==='piano'?1:kind==='guitar'?0:-1;
    this.voices.forEach(v=>{ if(v.rel||v.t0>=when||v.drum||(kind&&v.kind!==kind)) return; v.rel=true; try{ v.g.gain.setTargetAtTime(0,t,tc); v.src.stop(t+tc*8); }catch(_){} });
    this.offs.forEach(o=>{ if(o.ch<2&&(chOf<0||o.ch===chOf)&&o.t0<when&&o.time>when) o.time=when; });   // banque de sons : les extinctions en attente sont avancées à l'instant du changement d'accord
  },
  silence(){
    const c=this.ctx; if(!c) return; const t=c.currentTime;
    this.voices.forEach(v=>{ v.rel=true; try{ v.g.gain.cancelScheduledValues(t); v.g.gain.setTargetAtTime(0,t,0.03); v.src.stop(t+0.25); }catch(_){} });
    this.sfSilence();
  },
  halt(){   // arrête le planificateur, sans couper les notes qui sonnent encore
    clearInterval(this.timer); this.timer=null;
    if(this.seq){ this.seq.ui.forEach(clearTimeout); this.seq=null; }
  },
  stop(){ this.halt(); this.silence(); if(this.sf&&this.kit){ this.kit=0; try{ this.sf.programChange(9,0); }catch(_){} } },
  // --- Accompagnement du moteur (basse 2, claviers 1, batterie 9) : note MIDI datée, longueur dur en secondes ---
  kit:0,
  setKit(p){ this.kit=p; if(this.sf) this.sf.programChange(9,p); },
  play(track,pitch,vel,when,dur){
    if(!this.ctx) return;
    const f=Math.max(0.05,Math.min(1,vel/127));
    if(this.sfOn()){
      const ch=track==='bass'?2:track==='piano'?1:9, off=track==='drums'?0.4:Math.max(0.06,dur);
      this.offs.forEach(o=>{ if(o.ch===ch&&o.key===pitch&&o.time>when-0.004&&ch!==9) o.time=Math.max(o.t0,when-0.004); });
      this.sf.noteOn(ch,pitch,Math.max(1,Math.min(127,vel)),{time:when-this.lag}); this.offs.push({time:when+off,t0:when,ch,key:pitch});
      if(!this.offTimer) this.offTimer=setInterval(()=>this.sfPump(),30);
    } else if(track==='bass') this.bass(pitch,when,Math.max(0.1,dur),f);
    else if(track==='piano') this.note('piano',pitch,when,0.45*f);
    else { const k=DRUM_KIND[pitch]||(pitch>=47&&pitch<=52?'ride':pitch>=35&&pitch<=36?'kick':pitch>=37&&pitch<=40?'snare':'hat'); this.drum(k,when,f); }
  },
  // Les échantillons d'un SF3 sont décompressés à la première note qui les utilise : on joue donc une fois en silence les notes de batterie du moteur (une seule fois par kit).
  warmedKits:{},
  sfWarmKit(kit,pitches,done){
    const s=this.sf; if(!s||this.warmedKits[kit]){ done(); return; }
    this.warmedKits[kit]=true; this.drumGo=false; s.controllerChange(9,7,0); s.programChange(9,kit); this.kit=kit;
    const jobs=[]; pitches.forEach(p=>[60,115].forEach(v=>jobs.push([p,v]))); let i=0;
    const step=()=>{ if(this.sf!==s) return done(); if(i>=jobs.length){ s.controllerChange(9,7,DRUM_VOL); this.drumGo=true; return done(); }
      for(let n=0;n<3&&i<jobs.length;n++){ const [k,v]=jobs[i++]; s.noteOn(9,k,v); s.noteOff(9,k); } setTimeout(step,50); };
    step();
  },
  hear(kind,notes){   // un accord isolé
    if(!this.ready()) return false;
    this.stop(); if(!this.sfOn()) notes.forEach(m=>this.buffer(kind,m));   // sons intégrés : notes préparées avant de lire l'horloge
    this.chord(kind,notes,this.ctx.currentTime+0.03); return true;
  },
  // Suite de n pas (des temps) : onStep(k,when) est appelé un peu avant chaque pas, avec son heure sur l'horloge audio.
  // stepSec et o.loop peuvent être des fonctions (le tempo se règle en cours de lecture). o.onUi(k) est appelé à l'heure du pas,
  // o.onEnd() à la fin de la dernière mesure (les notes déjà lancées finissent de sonner).
  sequence(stepSec,n,onStep,o={}){
    if(!this.ready()) return false;
    this.halt(); this.silence();   // pas stop() : le kit de batterie choisi avant l'appel doit rester
    const c=this.ctx, sec=()=>typeof stepSec==='function'?stepSec():stepSec, lp=()=>typeof o.loop==='function'?o.loop():!!o.loop;
    const s={i:0,next:c.currentTime+0.2,ui:[],endT:null}; this.seq=s;
    const tick=()=>{
      while(s.endT===null&&s.next<c.currentTime+0.25){
        if(s.i>=n){ if(lp()) s.i=o.loopFrom||0; else { s.endT=s.next; break; } }
        const when=s.next, k=s.i; onStep(k,when);
        if(o.onUi){ s.ui.push(setTimeout(()=>{ if(this.seq===s) o.onUi(k); },Math.max(0,(when-c.currentTime)*1000))); if(s.ui.length>64) s.ui.shift(); }
        s.i++; s.next+=sec();
      }
      if(s.endT!==null&&c.currentTime>=s.endT){ this.halt(); if(o.onEnd) o.onEnd(); }
    };
    this.timer=setInterval(tick,25); tick(); return true;
  }
};
// --- Interface d'écoute ---
const playB=$('playB'), bpmSel=$('bpm'), loopB=$('loopB'), sndSel=$('snd'), sndMsg=$('sndMsg');
const setSndMsg=t=>{ sndMsg.textContent=t; };
let listening=false, listenSig='', nowI=-1, nowK=-1;

/* ===== 75-listen-train.js ===== */
const sigNow=()=>[BPB,tab,chords.join(),capoSel.value,$('lvl').value,JSON.stringify(ov),JSON.stringify(ovP)].join('|');
function runOf(i){ let k=-1, prev=null; for(let j=0;j<=i;j++){ if(chords[j]!==prev){ k++; prev=chords[j]; } } return k; }   // numéro de la série (diagramme) qui contient le temps i
function markNow(i,k){
  nowI=i; nowK=k; document.querySelectorAll('.now').forEach(e=>e.classList.remove('now'));
  if(i<0) return;
  const a=document.querySelector(`#slots .beat[data-b="${i}"]`), b=document.querySelector(`#grid .card[data-i="${k}"]`);
  if(a) a.classList.add('now');
  if(b){ b.classList.add('now'); if(b.scrollIntoView) b.scrollIntoView({block:'nearest'}); }
}
function setListening(on){
  listening=on; playB.textContent=on?'Arrêter':'Écouter la grille'; playB.setAttribute('aria-pressed',String(on));
  if(on) listenSig=sigNow(); else markNow(-1,-1);
}
function stopListen(){ Snd.stop(); setListening(false); }
// Appelée après chaque affichage : la lecture s'arrête si la grille, le capo, le niveau, un choix ou l'onglet ont changé ; sinon on remet la mesure en cours en évidence.
function listenCheck(){ accCheck(); if(!listening) return; if(sigNow()!==listenSig) stopListen(); else if(nowI>=0) markNow(nowI,nowK); }
// Notes d'un diagramme choisi (null si la page n'en propose pas)
function notesOf(c){ return !c?[]:tab==='g'?guitarNotes(c.f,+capoSel.value):pianoNotes(c); }
const kindNow=()=>tab==='g'?'guitar':'piano';
function hearRun(k){
  const c=(tab==='g'?model(ov):modelP(ovP)).chosen[k], notes=notesOf(c); if(!notes.length) return;
  if(listening) setListening(false);
  if(!Snd.hear(kindNow(),notes)) vmsg(NOSOUND);
}
function startListen(){
  if(accOn) stopAcc();
  const m=tab==='g'?model(ov):modelP(ovP), kind=kindNow();
  const beats=chords.map((_,i)=>{ const k=runOf(i); return {k,notes:notesOf(m.chosen[k])}; });   // un pas = un temps
  if(!beats.length) return;
  setListening(true);
  const ok=Snd.sequence(()=>60/(+bpmSel.value||80),beats.length,(s,when)=>{
    if(s%BPB&&chords[s]===chords[s-1]) return;   // une frappe au début de chaque mesure et à chaque changement d'accord
    const b=beats[s];
    Snd.release(when,0.05); if(b.notes.length) Snd.chord(kind,b.notes,when);
  },{loop:()=>loopB.checked,onUi:s=>markNow(s,beats[s].k),onEnd:()=>setListening(false)});
  if(!ok){ setListening(false); vmsg(NOSOUND); }
}
playB.onclick=()=>{ if(listening) stopListen(); else startListen(); };
$('hear').onclick=()=>hearRun(runOf(cur));
bpmSel.onchange=()=>pref('bpm',bpmSel.value); loopB.onchange=()=>pref('loop',loopB.checked?'1':'0');
{ const b=pref('bpm'); if(b&&[...bpmSel.options].some(o=>o.value===b)) bpmSel.value=b; loopB.checked=pref('loop')==='1'; }
// Son : la banque de sons est le choix par défaut (guitare acier) ; « Intégré » = synthèse de la page, sans fichier. Réglage mémorisé.
{ const v=pref('sound'); if(v&&[...sndSel.options].some(o=>o.value===v)) sndSel.value=v; }
sndSel.onchange=()=>{
  pref('sound',sndSel.value);
  if(sndSel.value==='builtin'){ setSndMsg(''); return; }
  if(Snd.sfState==='ready'){ Snd.sfProgram(); Snd.warmed=false; Snd.sfWarm(); setSndMsg('Banque de sons prête.'); }
  else { if(Snd.sfState==='failed'){ Snd.sfp=null; Snd.sfState='idle'; } Snd.sfFetch(); }
};
if(sndSel.value!=='builtin') Snd.sfFetch();   // dès l'ouverture : depuis le cache du service worker, c'est immédiat
// --- Mode entraînement : métronome ou boîte à rythme, accord courant en grand, suivant en aperçu, compteur de changements par minute ---
const trEl=$('tr'), trBpm=$('trBpm'), trRy=$('trRy'), trCh=$('trCh'), trBs=$('trBs'), trPn=$('trPn'), trGo=$('trGo'); let trDots=[];
function trBuildDots(){ const el=$('trBeats'); el.innerHTML='<i></i>'.repeat(BPB); trDots=[...el.children]; }   // un point par temps de la mesure en cours
const tgOn=b=>b.getAttribute('aria-checked')==='true', tgSet=(b,v)=>b.setAttribute('aria-checked',String(!!v));   // bascule tactile (bouton) plutôt que petite case à cocher
let training=false, trWait=false, trWake=null, trShown='';
RHYTHMS.forEach(r=>{ const o=document.createElement('option'); o.value=r.id; o.textContent=r.name; trRy.appendChild(o); });
const trTempo=()=>Math.min(240,Math.max(30,Math.round(+trBpm.value)||80));
const frNum=v=>(Math.round(v*10)/10).toString().replace('.',',');
function trCpm(){
  const n=chords.length, v=changesPerMin(chords,trTempo());
  $('trCpm').textContent=!v?'Il faut au moins deux accords différents dans la grille pour compter des changements.':`À ${trTempo()} battements par minute : environ ${frNum(v)} changement${v>=2?'s':''} d'accord par minute.`;
}
function trDia(el,k){   // diagramme de la série k (même dessin que dans la grille), vide si la page n'en propose pas
  const m=tab==='g'?model(ov):modelP(ovP), c=m.chosen[k];
  el.innerHTML=c?(tab==='g'?svg(c,null):svgP(c,null)):'';
}
// s = temps courant dans la grille (0 = premier temps de la première mesure) ; s < 0 : arrêt
function nextChangeAfter(s){ const n=chords.length; for(let d=1;d<=n;d++){ const j=(s+d)%n; if(chords[j]!==chords[s]) return j; } return s; }
function trShow(s){
  const n=chords.length; if(!n) return;
  const at=Math.max(0,s), beat=s<0?-1:s%BPB, nx=nextChangeAfter(at), key=[tab,runOf(at),runOf(nx),JSON.stringify(ov),JSON.stringify(ovP),capoSel.value,chords[at],chords[nx]].join('|');
  if(key!==trShown){ trShown=key;
    $('trCur').textContent=chords[at]; $('trNxt').textContent=chords[nx];
    trDia($('trDia'),runOf(at)); trDia($('trNDia'),runOf(nx)); }
  trDots.forEach((d,i)=>{ d.classList.toggle('on',i<=beat); d.classList.toggle('one',i===0); });
  $('trNext').classList.toggle('soon',s>=0&&chords[(at+1)%n]!==chords[at]);
  $('trBar').textContent=s<0?'':`Mesure ${barOf(at)} sur ${n/BPB} · temps ${beat+1}`;
}
function trSetRunning(on){
  training=on; trGo.textContent=on?'Arrêter':'Démarrer'; trGo.setAttribute('aria-pressed',String(on));
  try{
    if(on&&navigator.wakeLock&&!trWake) navigator.wakeLock.request('screen').then(w=>{ trWake=w; if(!training) { w.release(); trWake=null; } },()=>{});   // l'écran reste allumé pendant l'entraînement
    if(!on&&trWake){ trWake.release(); trWake=null; }
  }catch(_){}
  if(!on){ trShown=''; trShow(-1); }
}
function trStop(){ Snd.stop(); trSetRunning(false); }
function trCancelWait(){ trWait=false; trGo.textContent='Démarrer'; $('trBar').textContent=''; }
async function trStart(){
  if(!chords.length){ $('trBar').textContent="Ajoutez d'abord des accords à la grille."; return; }
  if(listening) stopListen(); if(accOn) stopAcc();
  if(!Snd.ready()){ $('trBar').textContent=NOSOUND; return; }
  const loading=()=>sndSel.value!=='builtin'&&['fetching','fetched','building'].includes(Snd.sfState);
  if(loading()){   // la batterie de la banque n'est pas encore prête : on attend (au plus 6 s) pour ne pas mélanger deux timbres
    trWait=true; trGo.textContent='Annuler'; $('trBar').textContent='Préparation des sons…'; const t0=Date.now();
    while(trWait&&loading()&&Date.now()-t0<6000) await new Promise(r=>setTimeout(r,40));
    if(!trWait) return; trCancelWait();
  }
  const m=tab==='g'?model(ov):modelP(ovP), kind=kindNow(), n=chords.length;
  const beats=chords.map((_,i)=>({notes:notesOf(m.chosen[runOf(i)])}));
  const pm=modelP(ovP), keys=chords.map((_,i)=>{ const c=pm.chosen[runOf(i)]; return c?pianoNotes(c):[]; });   // clavier : les accords de piano de la grille (renversements choisis compris)
  trSetRunning(true);
  const ok=Snd.sequence(()=>60/trTempo(),n,(s,when)=>{
    const beat=s%BPB, bar=(s-beat)/BPB, d=60/trTempo(), rh=RHYTHMS.find(r=>r.id===trRy.value)||RHYTHMS[1];   // rythme et tempo se règlent en cours de route
    rh.hitsFor(BPB).forEach(([p,dr,f])=>{ if(p>=beat-1e-9&&p<beat+1-1e-9) Snd.drum(dr,when+(p-beat)*d,f); });
    if((beat===0||chords[s]!==chords[s-1])&&tgOn(trCh)){ Snd.release(when,0.05); const b=beats[s]; if(b.notes.length) Snd.chord(kind,b.notes,when); }
    if(tgOn(trPn)){ const hits=compHits(rh.id,BPB).filter(p=>p>=beat-1e-9&&p<beat+1-1e-9); if(chords[s]!==chords[s-1]&&beat>0&&!hits.includes(beat)) hits.push(beat);
      hits.forEach(p=>{ const t=when+(p-beat)*d; Snd.release(t,0.05,'piano'); if(keys[s].length) Snd.chord('piano',keys[s],t); }); }
    // basse : le motif du rythme, joué sur l'accord de ce temps ; la dernière figure de la mesure mène à l'accord qui ouvre la mesure suivante
    if(tgOn(trBs)) bassLine(rh.id,parse(chords[s]),parse(chords[((bar+1)*BPB)%n]),BPB).forEach(([p,midi,len,f])=>{ if(p>=beat-1e-9&&p<beat+1-1e-9) Snd.bass(midi,when+(p-beat)*d,len*d*0.92,f); });
  },{loop:true,onUi:s=>trShow(s),onEnd:()=>trSetRunning(false)});
  if(ok) Snd.drumsReady(); else { trSetRunning(false); $('trBar').textContent=NOSOUND; }
}
function trOpen(){
  if(accOn) stopAcc(); if(listening) stopListen(); Snd.stop();
  trEl.classList.add('open'); trShown=''; trBuildDots(); trShow(-1); trCpm();
  Snd.wantDrums=true; Snd.ready();   // l'ouverture est un geste : le synthé de la banque se construit tout de suite et préchauffe la batterie dès qu'il est prêt
  if(Snd.sf&&Snd.sfOn()) Snd.sfWarmDrums();
  trGo.focus();
}
function trClose(){ if(trWait) trCancelWait(); if(training) trStop(); trEl.classList.remove('open'); Snd.wantDrums=false; $('trainB').focus(); }
$('trainB').onclick=trOpen; $('trX').onclick=trClose; trGo.onclick=()=>{ if(training) trStop(); else if(trWait) trCancelWait(); else trStart(); };
const trSetTempo=v=>{ trBpm.value=Math.min(240,Math.max(30,Math.round(v)||80)); pref('trBpm',trBpm.value); trCpm(); };
$('trM').onclick=()=>trSetTempo(trTempo()-5); $('trP').onclick=()=>trSetTempo(trTempo()+5);
trBpm.onchange=()=>trSetTempo(+trBpm.value); trBpm.oninput=trCpm;
trRy.onchange=()=>pref('trRy',trRy.value);
trCh.onclick=()=>{ tgSet(trCh,!tgOn(trCh)); pref('trCh',tgOn(trCh)?'1':'0'); }; trPn.onclick=()=>{ tgSet(trPn,!tgOn(trPn)); pref('trPn',tgOn(trPn)?'1':'0'); }; trBs.onclick=()=>{ tgSet(trBs,!tgOn(trBs)); pref('trBs',tgOn(trBs)?'1':'0'); };
{ const b=+pref('trBpm'); if(b>=30&&b<=240) trBpm.value=Math.round(b); const r=pref('trRy'); if(r&&RHYTHMS.some(x=>x.id===r)) trRy.value=r; else trRy.value='bin'; tgSet(trCh,pref('trCh')==='1'); tgSet(trBs,pref('trBs')==='1'); tgSet(trPn,pref('trPn')==='1'); }
document.addEventListener('keydown',e=>{ if(e.key==='Escape'&&trEl.classList.contains('open')) trClose(); });
document.addEventListener('visibilitychange',()=>{ if(document.hidden&&accOn) stopAcc(); if(document.hidden&&listening) stopListen(); if(document.hidden&&training) trStop(); });   // en arrière-plan, les minuteurs sont ralentis : le tempo ne tiendrait plus
// ==/AUDIO==

/* ===== 76-accomp.js ===== */
// ==ACCOMP==
// Accompagnement automatique : la grille (un accord par temps) est envoyée au moteur JJEngine (src/engine : port de JJSwing), qui rend des notes
// de basse, de batterie et de piano en temps musicaux. On les range par « tic » (24 par temps) et le planificateur de Snd les joue ; les pistes
// se coupent à volonté pendant la lecture. Les diagrammes choisis par le solveur (guitare ou piano selon l'onglet) peuvent jouer en plus.
const TPB=24;   // tics par temps
const accEl=$('acc'), accB=$('accB'), accStyle=$('accStyle'), accCount=$('accCount'), accMsg=$('accMsg');
const accTg={bass:$('accBs'),drums:$('accDr'),piano:$('accPn'),guitar:$('accGt')};
let accOn=false, accSig='', accSeed=1+Math.floor(Math.random()*99999), accBusy=false;
const accHas=typeof JJEngine!=='undefined';
if(!accHas) accEl.style.display='none';
else {
  { const v=pref('accStyle'); accStyleFill(v); const c=pref('accCount'); if(c&&['0','1','2'].includes(c)) accCount.value=c;
    Object.entries(accTg).forEach(([k,b])=>{ const p=pref('acc_'+k); if(p!==null) tgSet(b,p==='1'); }); }
}
// Les styles proposés dépendent de la mesure (le jazz sait jouer à 3, 4 et 5 temps ; la valse à 3 et 6 ; le pop/rock à 4)
function accStyleFill(want){
  if(!accHas) return; const keep=want||accStyle.value; accStyle.textContent='';
  JJEngine.styles(engineMeter()).forEach(s=>{ let g=[...accStyle.children].find(o=>o.label===s.group); if(!g){ g=document.createElement('optgroup'); g.label=s.group; accStyle.appendChild(g); } const o=document.createElement('option'); o.value=s.id; o.textContent=s.name; g.appendChild(o); });
  if(keep&&[...accStyle.querySelectorAll('option')].some(o=>o.value===keep)) accStyle.value=keep;
}
// Jeu du piano (options du moteur) : trois choix à boutons, mémorisés ; un changement pendant la lecture relance avec le même tirage
const PJ={pjMode:['patterns','pianoMode'],pjApp:['none','pianoApp'],pjInt:['0','pianoInt']};
const pjVal=id=>{ const b=document.querySelector('#'+id+' [aria-checked="true"]'); return b?b.dataset.v:PJ[id][0]; };
Object.entries(PJ).forEach(([id,[def,key]])=>{ const box=$(id), v=pref(key); if(v&&[...box.children].some(b=>b.dataset.v===v)) [...box.children].forEach(b=>b.setAttribute('aria-checked',String(b.dataset.v===v)));
  box.onclick=e=>{ const b=e.target.closest('button'); if(!b) return; [...box.children].forEach(x=>x.setAttribute('aria-checked',String(x===b))); pref(key,b.dataset.v); if(accOn){ stopAcc(); startAcc(); } }; });
const accSetMsg=t=>{ accMsg.textContent=t; };
function accSetRunning(on){ accOn=on; accB.textContent=on?'Arrêter':'Jouer avec accompagnement'; accB.setAttribute('aria-pressed',String(on)); if(on) accSig=sigNow(); else markNow(-1,-1); }
function stopAcc(){ Snd.stop(); accSetRunning(false); accSetMsg(''); }
// Appelée à chaque affichage : la grille, le capo, le niveau ou un choix ont changé -> l'accompagnement généré ne correspond plus, on arrête
function accCheck(){ if(accOn&&!accBusy&&sigNow()!==accSig) stopAcc(); }
const accTempo=()=>+bpmSel.value||100;
async function startAcc(){
  if(!accHas||accBusy) return;
  if(listening) stopListen(); if(training) trStop();
  if(!chords.length){ accSetMsg("Ajoutez d'abord des accords à la grille."); return; }
  if(!Snd.ready()){ accSetMsg(NOSOUND); return; }
  accBusy=true; accB.disabled=true; accSetMsg('Préparation…');
  try{
    await new Promise(r=>setTimeout(r,20));   // laisse l'écran afficher le message avant le calcul
    const st=JJEngine.styles(engineMeter()).find(s=>s.id===accStyle.value)||JJEngine.styles(engineMeter())[0], tempo=Math.min(300,Math.max(40,accTempo()));
    const g=JJEngine.generate({chordText:engineText(chords),tempo,style:st.id,seed:accSeed,meter:BPB,pianoMode:pjVal('pjMode'),pianoApproach:pjVal('pjApp'),pianoIntensity:+pjVal('pjInt'),pianoNotesPerBar:2});
    // la banque de sons : kit de batterie du style, notes de batterie préchauffées (une fois par kit)
    if(Snd.sfOn()){ const ps=[...new Set(g.events.filter(e=>e.track==='drums').map(e=>e.pitch))]; await new Promise(r=>Snd.sfWarmKit(g.kit,ps,r)); }
    else if(Snd.sf) Snd.setKit(g.kit);
    if(Snd.sfOn()) Snd.setKit(g.kit);
    const lenTicks=Math.round(g.lengthBeats*TPB), cb=+accCount.value*BPB, cTicks=cb*TPB;
    const slots=Array.from({length:lenTicks},()=>null);
    g.events.forEach(e=>{ const k=Math.min(lenTicks-1,Math.max(0,Math.round(e.beat*TPB))); (slots[k]||(slots[k]=[])).push(e); });
    const mdl=tab==='g'?model(ov):modelP(ovP), kind=kindNow();
    const notesAt=chords.map((_,i)=>notesOf(mdl.chosen[runOf(i)]));
    accSetRunning(true); accSetMsg(''); const sec=()=>60/accTempo()/TPB;
    const total=cTicks+lenTicks;
    const ok=Snd.sequence(sec,total,(s,when)=>{
      const d=sec()*TPB;   // durée d'un temps (le tempo se règle en cours de lecture)
      if(s<cTicks){ if(s%TPB===0){ const b=s/TPB; Snd.drum(b%BPB===0?'clickHi':'clickLo',when,1); } return; }
      const k=s-cTicks;
      (slots[k]||[]).forEach(e=>{ if(tgOn(accTg[e.track])) Snd.play(e.track,e.pitch,e.vel,when,e.dur*d*0.97); });
      if(k%TPB===0&&tgOn(accTg.guitar)){ const b=k/TPB; if(b%BPB===0||chords[b]!==chords[b-1]){ Snd.release(when,0.05,kind==='guitar'?'guitar':'piano'); const n=notesAt[b]; if(n.length) Snd.chord(kind,n,when); } }
    },{loop:()=>loopB.checked,loopFrom:cTicks,onUi:s=>{ if(s<cTicks){ if(s%TPB===0) accSetMsg('Décompte… '+(s/TPB%BPB+1)); return; } if(s===cTicks) accSetMsg(''); const k=s-cTicks; if(k%TPB===0){ const b=k/TPB; markNow(b,runOf(b)); } },onEnd:()=>{ accSetRunning(false); }});
    if(!ok){ accSetRunning(false); accSetMsg(NOSOUND); }
  }catch(e){ accSetRunning(false); accSetMsg("L'accompagnement n'a pas pu être généré : "+(e&&e.message?e.message:e)); }
  accBusy=false; accB.disabled=false;
}
accB.onclick=()=>{ if(accOn) stopAcc(); else startAcc(); };
accStyle.onchange=()=>{ pref('accStyle',accStyle.value); const st=JJEngine.styles(engineMeter()).find(s=>s.id===accStyle.value); if(st){ const o=[...bpmSel.options].map(x=>+x.value).reduce((a,b)=>Math.abs(b-st.tempo)<Math.abs(a-st.tempo)?b:a); bpmSel.value=String(o); pref('bpm',bpmSel.value); }
  if(accOn){ stopAcc(); startAcc(); } };
accCount.onchange=()=>pref('accCount',accCount.value);
$('accNew').onclick=()=>{ accSeed=1+Math.floor(Math.random()*99999); if(accOn){ stopAcc(); startAcc(); } else accSetMsg('Nouvelle version prête : elle sera jouée au prochain départ.'); };
Object.entries(accTg).forEach(([k,b])=>{ b.onclick=()=>{ tgSet(b,!tgOn(b)); pref('acc_'+k,tgOn(b)?'1':'0'); }; });
// ==/ACCOMP==

/* ===== 80-lib-print.js ===== */
// ==LIB==
// Sauvegarde locale : dernière grille (automatique) et « Mes grilles » (nommées). Même format que les fichiers d'export
// et les liens (migrations comprises), donc relisible par les versions suivantes. Rien ne quitte l'appareil.
const CUR_KEY='current', LIB_KEY='library';
let baseline=null, saveTimer=null, armedDel=null;
const currentDoc=()=>({...buildShare(),locked});
function scheduleSave(){
  clearTimeout(saveTimer);
  saveTimer=setTimeout(()=>{ const s=JSON.stringify(currentDoc()); if(s!==baseline) pref(CUR_KEY,s); },300);
}
function startup(){
  customsLoad();
  if(/^#s=/.test(location.hash)){ loadFromHash(); return; }   // un lien partagé prime, sans écraser la dernière grille tant qu'on n'y touche pas
  let d=null; try{ d=JSON.parse(pref(CUR_KEY)||'null'); }catch(_){}
  const r=d?applyImport(d):{n:0,warnings:[]};
  if(r.n){ locked=!!d.locked; setTab(d.tab==='p'?'p':'g'); $('msg').textContent='Dernière grille rouverte.'+(r.warnings.length?' ⚠ '+r.warnings.join(' '):''); }
}
const libRead=()=>{ try{ const a=JSON.parse(pref(LIB_KEY)||'[]'); return Array.isArray(a)?a.filter(e=>e&&typeof e.id==='string'&&typeof e.name==='string'&&e.doc):[]; }catch(_){ return []; } };
const libWrite=a=>{ try{ localStorage.setItem('accords.'+LIB_KEY,JSON.stringify(a)); return true; }catch(_){ return false; } };
const closeL=()=>$('lsheet').classList.remove('open');
function drawLib(){
  const box=$('llist'), lib=libRead(); box.textContent='';
  if(!lib.length){ const p=document.createElement('p'); p.className='hint'; p.textContent='Aucune grille enregistrée pour le moment.'; box.appendChild(p); return; }
  lib.slice().sort((a,b)=>String(b.savedAt).localeCompare(String(a.savedAt))).forEach(e=>{
    const row=document.createElement('div'); row.className='lrow';
    const meta=document.createElement('div'); meta.className='lmeta';
    const b=document.createElement('b'); b.textContent=e.name;
    const ev=Array.isArray(e.doc.events)?e.doc.events:[], dt=new Date(e.savedAt), nb=Math.round(+e.doc.bars)||0;
    const s=document.createElement('small'); s.textContent=[nb+' mesure'+(nb>1?'s':''),ev.slice(0,6).map(x=>String(x&&x.accord)).join(' ')+(ev.length>6?'…':''),isNaN(dt)?'':dt.toLocaleDateString('fr-FR')].filter(Boolean).join(' · ');
    meta.append(b,s);
    const o=document.createElement('button'); o.textContent='Ouvrir'; o.dataset.a='open'; o.dataset.id=e.id;
    const d=document.createElement('button'); d.className='sec'; d.dataset.a='del'; d.dataset.id=e.id; d.textContent=armedDel===e.id?'Confirmer ?':'Supprimer';
    row.append(meta,o,d); box.appendChild(row);
  });
}
$('libB').onclick=()=>{ armedDel=null; $('lmsg').textContent=''; drawLib(); $('lsheet').classList.add('open'); $('lname').focus(); };
$('lok').onclick=closeL; $('lback').onclick=closeL;
$('lsave').onclick=()=>{
  const name=($('lname').value.trim()||('Grille du '+new Date().toLocaleDateString('fr-FR'))).slice(0,60);
  const lib=libRead(), i=lib.findIndex(e=>e.name.toLowerCase()===name.toLowerCase());
  const entry={id:i>=0?lib[i].id:'g'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),name,savedAt:new Date().toISOString(),doc:buildExport()};
  if(i>=0) lib[i]=entry; else lib.push(entry);
  if(libWrite(lib)){ $('lmsg').textContent=i>=0?`Grille « ${name} » mise à jour.`:`Grille « ${name} » enregistrée.`; $('lname').value=''; armedDel=null; drawLib(); }
  else $('lmsg').textContent="Enregistrement impossible : l'espace de stockage de cet appareil est plein ou désactivé.";
};
$('llist').onclick=e=>{
  const b=e.target.closest('button'); if(!b) return;
  const lib=libRead(), ent=lib.find(x=>x.id===b.dataset.id); if(!ent) return;
  if(b.dataset.a==='open'){
    const r=applyImport(ent.doc);
    if(r.n){ setTab(tab); closeL(); $('msg').textContent=`Grille « ${ent.name} » ouverte.`+(r.warnings.length?' ⚠ '+r.warnings.join(' '):''); }
    else $('lmsg').textContent="Cette grille n'a pas pu être relue.";
  } else if(armedDel===ent.id){
    armedDel=null; $('lmsg').textContent=libWrite(lib.filter(x=>x.id!==ent.id))?`Grille « ${ent.name} » supprimée.`:'Suppression impossible.'; drawLib();
  } else {
    armedDel=ent.id; drawLib(); setTimeout(()=>{ if(armedDel===ent.id){ armedDel=null; drawLib(); } },3000);
  }
};
// ==/LIB==
startup();

// ==PRINT==
// Impression par le navigateur : l'en-tête (titre, grille, réglages) est rempli juste avant ; le reste est géré par le CSS @media print.
function fillPrintHead(){
  const ph=$('printHead'); ph.textContent='';
  const el=(t,s)=>{ const e=document.createElement(t); e.textContent=s; return e; };
  const bits=[tab==='g'?'Guitare':'Piano'];
  if(tab==='g'&&+capoSel.value>0) bits.push('Capo case '+capoSel.value);
  bits.push($('lvl').value==='easy'?'Accords simplifiés':'Accords complets');
  if(pivots) bits.push('En jaune : '+(tab==='g'?'les doigts':'les notes')+' qui restent en place par rapport à l\'accord précédent');
  ph.append(el('h2',"Grille d'accords"),el('p',gridText(chords)),el('p',bits.join(' · ')),el('p',new Date().toLocaleDateString('fr-FR')+" · Diagrammes d'accords "+APP_VERSION));
}
window.addEventListener('beforeprint',fillPrintHead);
$('prtB').onclick=()=>{ fillPrintHead(); try{ window.print(); }catch(_){ vmsg("L'impression n'est pas disponible ici : ouvrez l'appli dans le navigateur."); } };
// ==/PRINT==
$('ver').textContent=`Version ${APP_VERSION} · format de fichier ${SCHEMA_VERSION} · symboles d'accords ${CHORD_LIB_VERSION} · doigtés guitare : ${DB_VERSION}`;
render();
